head.script:
scwin.screenId = "jldfil35704";

///////// 1. 변수 및 선언 영역 /////////

scwin.subTitle1 = $c.util.getComponent('subTitle1');

scwin.data = null;

scwin.calType = '';


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        await scwin.fn_init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil35704.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { $c.data.recvParamData('dma_pageContext'); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil35704.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fn_init
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_init = async function () {
    scwin.data = ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).dataArr);
    if (!Array.isArray(scwin.data)) { console.warn('[sdd] 인쇄 데이터 부재(호스트 진입 필요) — jldfil35704'); return; }
    let strCalc = "";
    let strListTp = "";
    if (scwin.data[0] == null && scwin.data[1] == null && scwin.data[2] == null && scwin.data[3] == null && scwin.data[4] == null && scwin.data[5] == null && scwin.data[6] == null && scwin.data[7] == null && scwin.data[8] == null && scwin.data[9] == null) {
        if (scwin.data[10].mkt_gubun === "1") {
            switch (scwin.data[10].listTp_gubun) {
                case '1':
                strListTp = "신규상장";
                break;
                case '2':
                strListTp = "추가/재상장";
                break;
                case '3':
                strListTp = "변경상장";
                break;
            }
            switch (scwin.data[10].calc_gubun) {
                case '1':
                strCalc = "보통주권/외국주권/종류주권/기업인수목적회사주권";
                break;
                case '2':
                strCalc = "집합투자증권";
                break;
                case '3':
                strCalc = "수익증권";
                break;
                case '4':
                strCalc = "신주인수권증권 ";
                break;
            }
            scwin.subTitle1.setStyle("display", 'block');
            $c.util.getComponent("ipt_mktGubun").setValue("유가증권시장");
            $c.util.getComponent("ipt_calcGubun").setValue(strCalc);
            $c.util.getComponent("ipt_listTpGubun").setValue(strListTp);
        } else {
            if (scwin.data[10].mkt_gubun === "2") {
                $c.util.getComponent("ipt_mktGubun").setValue("코스닥시장");
                if (scwin.data[10].calc_gubun === "1") {
                    $c.util.getComponent("ipt_calcGubun").setValue("주권/외국주권/외국주식예탁증권(DR)");
                } else {
                    if (scwin.data[10].calc_gubun === "6") {
                        $c.util.getComponent("ipt_calcGubun").setValue("신주인수권증권");
                    }
                }
                scwin.subTitle1.setStyle("display", '');
                if (scwin.data[10].listTp_gubun === "1") {
                    $c.util.getComponent("ipt_listTpGubun").setValue("신규상장");
                } else {
                    if (scwin.data[10].listTp_gubun === "2") {
                        $c.util.getComponent("ipt_listTpGubun").setValue("추가/재상장");
                    }
                }
            } else {
                if (scwin.data[10].mkt_gubun === "6") {
                    $c.util.getComponent("ipt_mktGubun").setValue("코넥스시장");
                    $c.util.getComponent("ipt_calcGubun").setValue("주권");
                    scwin.subTitle1.setStyle("display", '');
                    $c.util.getComponent("ipt_listTpGubun").setValue("신규/변경(자본금증가)/재/추가상장");
                } else {
                    if (scwin.data[10].mkt_gubun === "D") {
                        $c.util.getComponent("ipt_mktGubun").setValue("신종증권");
                        switch (scwin.data[10].calc_gubun) {
                            case '1':
                            strCalc = "신탁수익증권";
                            break;
                            case '2':
                            strCalc = "투자계약증권";
                            break;
