    $c.util.getComponent("ipt_totListAmt").setValue(scwin.data[11].tot_list_amt);
    $c.util.getComponent("ipt_listCommSum").setValue(scwin.data[11].list_comm_sum);
    $c.util.getComponent("ipt_listCommSumMin").setValue(scwin.data[11].list_comm_sum_min);
