    $c.win.popupPrint();
};


/**
 * @method
 * @name scwin.unformat
 * @author Inswave
 * @date 2026. 09. 06
 * @param obj
 * @returns
 * @hidden N
*/
scwin.unformat = function (obj) {
    let temp = "";
    let n = String(obj.value);
    let len = n.length;
    let pos = 0;
    let ch = '';
    while (pos < len) {
        ch = n.charAt(pos);
        if (((ch >= '0') && (ch <= '9')) || (ch === '-')) {
            temp = temp + ch;
        }
        pos = pos + 1;
    }
    obj.value = temp;
    return true;
};


/**
 * @method
 * @name scwin.numFormat
 * @author Inswave
 * @date 2026. 09. 06
 * @param obj
 * @returns
 * @hidden N
*/
scwin.numFormat = async function (obj) {
    if (obj.value !== "" && !scwin.isMinusNum(obj.value)) {
        obj.value = "";
        await $c.win.alert("숫자만 입력가능합니다.");
        obj.focus();
        return;
    }
    scwin.unformat(obj);
    if (obj.value === "") {
        return;
    }
    if (isNaN(obj.value)) {
        obj.value = "";
        return;
    }
    let str = Number(obj.value) + "";
    let sMinusChar = "";
    if (Number(obj.value) < 0) {
        str = str.substring(1);
        sMinusChar = "-";
    }
    let leng = str.length;
    let size = 3;
    let cnt = Math.floor(leng / size);
    let pos = leng % size;
    let result = "";
    if (cnt === 0) {
        obj.value = Number(obj.value);
        return;
    }
    for (let i = cnt; i > 0; i = i - 1) {
        result = "," + str.substr(pos + (i - 1) * size, size) + result;
    }
    if (result !== '') {
        if (pos === 0) {
            obj.value = sMinusChar + result.substring(1);
        } else {
            obj.value = sMinusChar + str.substr(0, pos) + result;
        }
    }
    return;
};


/**
 * @method
 * @name scwin.isMinusNum
 * @author Inswave
 * @date 2026. 09. 06
 * @param name
 * @returns
 * @hidden N
*/
scwin.isMinusNum = function (name) {
    var ch = "\0";
    let flag = true;
    ch = name.charAt(0);
    flag = ((ch >= '0' && ch <= '9') || ch === '-') ? true : false;
    for (var i = 1, ch = name.charAt(i); (i < name.length) && (flag); ch = name.charAt(++i)) {
        if ((ch >= '0') && (ch <= '9')) {

        } else {
            flag = false;
        }
    }
    return flag;
};
